import json

# Load definitions from registry
with open('/tmp/ixp_invoice_registry.json') as f:
    ixp_d = json.load(f)
ixp_def = ixp_d['Data']['Node']

with open('/tmp/end_def.json') as f:
    end_d = json.load(f)
end_def = end_d['Data']['Node']

with open('/tmp/script_def.json') as f:
    script_d = json.load(f)
script_def = script_d['Data']['Node']

# Existing flow (with trigger + http definitions already in place)
with open('/work/output/artifacts/skill-flow-ixp-e2e-invoice-extraction-greenfield/InvoiceExtractionFlow/InvoiceExtractionFlow/InvoiceExtractionFlow.flow') as f:
    flow = json.load(f)

IXP_NODE_TYPE = ixp_def['nodeType']
IXP_VERSION = ixp_def['version']

# Build the flow
flow['nodes'] = [
    # 1. SharePoint connector trigger (already present)
    {
        "id": "newPdfInvoiceInSharepoint1",
        "type": "uipath.connector.trigger.uipath-microsoft-onedrive.file-created",
        "typeVersion": "1.0.0",
        "display": {"label": "New PDF Invoice in SharePoint"},
        "inputs": {
            "entryPointId": "6b02bbb3-bf6c-430b-9687-7975cd017887",
            "isDefaultEntryPoint": True
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "The return value of the connector trigger.",
                "source": "=result.response",
                "var": "output"
            }
        }
    },
    # 2. IxP extraction node
    {
        "id": "extractInvoiceFields1",
        "type": IXP_NODE_TYPE,
        "typeVersion": IXP_VERSION,
        "display": {"label": "Extract Invoice Fields (Invoice Model)"},
        "inputs": {
            "model": {
                "id": "ff973488-5d89-8035-86ac-f980b4be6deb",
                "modelName": "InvoiceIXP",
                "modelDisplayName": "InvoiceIXP",
                "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
                "folderName": "Shared",
                "folderPath": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
                "description": ""
            },
            "modelName": "InvoiceIXP",
            "projectName": "invoiceixp-cef0d447-ixp",
            "folderKey": "c4359cde-55f0-4f0e-9322-c6cdce74ab4c",
            "folderName": "Shared",
            "versionTag": "",
            "fileRef": "=js:$vars.newPdfInvoiceInSharepoint1.output.DownloadUrl",
            "pageRange": ""
        },
        "outputs": {
            "output": ixp_def['outputDefinition']['output'],
            "error": ixp_def['outputDefinition']['error']
        }
    },
    # 3. Script node: map IxP fields to SAP request body
    {
        "id": "buildSapPayload1",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Build SAP Request Payload"},
        "inputs": {
            "script": r"""
const fields = ($vars.extractInvoiceFields1.output && $vars.extractInvoiceFields1.output.ExtractionResult && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Fields) ? $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Fields : [];
const tables = ($vars.extractInvoiceFields1.output && $vars.extractInvoiceFields1.output.ExtractionResult && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument && $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Tables) ? $vars.extractInvoiceFields1.output.ExtractionResult.ResultsDocument.Tables : [];
function getField(name) {
  const f = fields.find(function(x) { return x.FieldName === name; });
  return (f && f.Values && f.Values.length > 0) ? f.Values[0] : null;
}
const lineItems = tables.length > 0 ? tables[0].Values : [];
return {
  invoiceNumber: getField('InvoiceNumber') || getField('invoice_number') || getField('Invoice Number'),
  vendor: getField('VendorName') || getField('vendor_name') || getField('Vendor') || getField('Supplier'),
  invoiceDate: getField('InvoiceDate') || getField('invoice_date') || getField('Invoice Date'),
  totalAmount: getField('TotalAmount') || getField('total_amount') || getField('Total Amount') || getField('Amount Due'),
  lineItems: lineItems,
  sourceFile: ($vars.newPdfInvoiceInSharepoint1.output) ? $vars.newPdfInvoiceInSharepoint1.output.FullName : null
};
"""
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "The return value of the script",
                "source": "=result.response",
                "var": "output"
            },
            "error": {
                "type": "object",
                "description": "Error information if the script fails",
                "source": "=result.Error",
                "var": "error"
            }
        }
    },
    # 4. HTTP POST to SAP (already present via node add)
    {
        "id": "postInvoiceDataToSap1",
        "type": "core.action.http.v2",
        "typeVersion": "2.3",
        "display": {"label": "POST Invoice Data to SAP"},
        "inputs": {
            "branches": [],
            "timeout": "PT15M",
            "retryCount": 0
        }
    },
    # 5. End
    {
        "id": "end1",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "End"},
        "inputs": {}
    }
]

flow['edges'] = [
    {
        "id": "e-trigger-ixp",
        "sourceNodeId": "newPdfInvoiceInSharepoint1",
        "sourcePort": "output",
        "targetNodeId": "extractInvoiceFields1",
        "targetPort": "input"
    },
    {
        "id": "e-ixp-script",
        "sourceNodeId": "extractInvoiceFields1",
        "sourcePort": "success",
        "targetNodeId": "buildSapPayload1",
        "targetPort": "input"
    },
    {
