existing_defs = {d['nodeType']: d for d in flow.get('definitions', [])}

# Add IxP, script, end definitions
existing_defs[IXP_NODE_TYPE] = ixp_def
existing_defs['core.action.script'] = script_def
existing_defs['core.control.end'] = end_def

flow['definitions'] = list(existing_defs.values())

# Update variables.nodes to include all data-producing nodes
flow['variables'] = {
    "nodes": [
        {
            "id": "newPdfInvoiceInSharepoint1.output",
            "type": "object",
            "description": "The return value of the connector trigger.",
            "binding": {"nodeId": "newPdfInvoiceInSharepoint1", "outputId": "output"}
        },
        {
            "id": "extractInvoiceFields1.output",
            "type": "object",
            "description": "IxP extraction result.",
            "binding": {"nodeId": "extractInvoiceFields1", "outputId": "output"}
        },
        {
            "id": "extractInvoiceFields1.error",
            "type": "object",
            "description": "IxP extraction error.",
            "binding": {"nodeId": "extractInvoiceFields1", "outputId": "error"}
        },
        {
            "id": "buildSapPayload1.output",
            "type": "object",
            "description": "SAP request payload.",
            "binding": {"nodeId": "buildSapPayload1", "outputId": "output"}
        },
        {
            "id": "buildSapPayload1.error",
            "type": "object",
            "description": "Script error.",
            "binding": {"nodeId": "buildSapPayload1", "outputId": "error"}
        },
        {
            "id": "postInvoiceDataToSap1.output",
            "type": "object",
            "description": "HTTP response object.",
            "binding": {"nodeId": "postInvoiceDataToSap1", "outputId": "output"}
        },
        {
            "id": "postInvoiceDataToSap1.error",
            "type": "object",
            "description": "HTTP error.",
            "binding": {"nodeId": "postInvoiceDataToSap1", "outputId": "error"}
        }
    ]
}

# Update layout
flow['layout'] = {
    "nodes": {
        "newPdfInvoiceInSharepoint1": {"position": {"x": 200, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
        "extractInvoiceFields1": {"position": {"x": 400, "y": 144}, "size": {"width": 96, "height": 96}, "collapsed": False},
