    json.dump(flow, f, indent=2)

print("FLOW_WRITTEN")
PYEOF

cd /work/output/artifacts/skill-flow-ixp-e2e-invoice-extraction-greenfield/InvoiceExtractionFlow/InvoiceExtractionFlow \
